import { Accessor, Component, createMemo, createSignal, For, onCleanup, onMount, Show } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { FiligreeTitle } from "#core/ui-next/components/filigree-title.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { OrnateCard } from "#core/ui-next/components/ornate-card.jsx";
import { PortraitIcon } from "#core/ui-next/components/portrait-icon.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { isMobile } from "#core/ui-next/services/view-experience.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";
import { createLayoutComplete } from "#core/ui-next/utilities/solid-utilities.js";

import { GamepadTrayItem, GamepadTrayItemProvider } from "#base/ui-next/components/gamepad-tray-item-provider.jsx";
import { CommerceScreenBaseTabContent } from "#base/ui-next/screens/commerce/commerce-screen-base-tab-content.jsx";
import { EmpireTabData, useCommerceScreenContext } from "#base/ui-next/screens/commerce/commerce-screen-model.js";

//#region EMPIRE RESOURCES
export const EmpireResourceContainer: Component<EmpireTabData> = (props) => {
	const model = useCommerceScreenContext();
	const isSmallScreen = useIsSmallScreen();
	let cardsRowRef: HTMLDivElement | undefined;
	let cardsRowResizeObserver: ResizeObserver | undefined;
	let isApplyingMeasuredWidths = false;
	let hasScheduledWrapCheck = false;
	const [empireResourceCardWidth, setEmpireResourceCardWidth] = createSignal<string | undefined>(undefined);
	const [hasCheckedForWrap, setHasCheckedForWrap] = createSignal(false);
	const [numCardsInFirstRow, setNumCardsInFirstRow] = createSignal(0);

	const empireCardMarginRight = createMemo(() => {
		return isMobile() ? Layout.pixelsToScreenPixels(28) : Layout.pixelsToScreenPixels(20);
	});

	const defaultEmpireCardWidth = createMemo(() => {
		return isMobile() ? Layout.pixelsToScreenPixels(isSmallScreen() ? 612 : 680) : Layout.pixelsToScreenPixels(384);
	});

	const applyMeasuredWidths = (applyFunction: () => void) => {
		isApplyingMeasuredWidths = true;
		applyFunction();
		delayByFrame(() => {
			isApplyingMeasuredWidths = false;
		});
	};

	const scheduleWrapCheck = () => {
		if (hasScheduledWrapCheck) {
			return;
		}
		hasScheduledWrapCheck = true;
		delayByFrame(() => {
			hasScheduledWrapCheck = false;
			checkForWrap();
		});
	};

	onMount(() => {
		cardsRowResizeObserver = new ResizeObserver(() => {
			if (isApplyingMeasuredWidths) {
				return;
			}
			scheduleWrapCheck();
		});

		if (cardsRowRef) {
			cardsRowResizeObserver.observe(cardsRowRef);
			scheduleWrapCheck();
		}
	});

	onCleanup(() => {
		cardsRowResizeObserver?.disconnect();
	});

	const checkForWrap = () => {
		if (!cardsRowRef) {
			return;
		}

		const availableWidth = cardsRowRef.clientWidth || 0;
		if (availableWidth <= 0) {
			return;
		}

		const rowCardCount = Math.max(
			1,
			Math.floor(
				(availableWidth + empireCardMarginRight()) / (defaultEmpireCardWidth() + empireCardMarginRight()),
			),
		);

		const cards = cardsRowRef.querySelectorAll(".empire-resource-card");
		if (cards.length === 0) {
			setHasCheckedForWrap(false);
			return;
		}

		const hasWrappedRows = cards.length > rowCardCount;
		if (!hasWrappedRows) {
			const needsWidthReset = empireResourceCardWidth() !== undefined;
			const needsRowCountReset = numCardsInFirstRow() !== 0;
			if (needsWidthReset || needsRowCountReset) {
				applyMeasuredWidths(() => {
					if (needsWidthReset) {
						setEmpireResourceCardWidth(undefined);
					}
					if (needsRowCountReset) {
						setNumCardsInFirstRow(0);
					}
					setHasCheckedForWrap(true);
				});
				return;
			}
			setHasCheckedForWrap(true);
			return;
		}

		const fittedWidth = (availableWidth - empireCardMarginRight() * rowCardCount) / rowCardCount;
		const nextWidth = Math.max(1, Math.floor(fittedWidth * 100) / 100) + "px";

		const needsRowCountUpdate = numCardsInFirstRow() !== rowCardCount;
		const needsWidthUpdate = empireResourceCardWidth() !== nextWidth;
		if (needsRowCountUpdate || needsWidthUpdate) {
			applyMeasuredWidths(() => {
				if (needsRowCountUpdate) {
					setNumCardsInFirstRow(rowCardCount);
				}
				if (needsWidthUpdate) {
					setEmpireResourceCardWidth(nextWidth);
				}
				setHasCheckedForWrap(true);
			});
			return;
		}

		setHasCheckedForWrap(true);
	};
	const layoutComplete = createLayoutComplete();

	const [focusedResourceCard, setFocusedResourceCard] = createSignal<number | undefined>();

	function shouldAutoFocusResourceCard(resourceValue: number, index: number) {
		if (!layoutComplete()) {
			return false;
		}
		if (focusedResourceCard() === undefined) {
			return index === 0;
		}
		return focusedResourceCard() === resourceValue;
	}

	function getResourceDefinitonFromResourceValue(resourceValue: number) {
		const uniqueResource = Players.get(GameContext.localPlayerID)
			?.Resources?.getResources()
			.find((uniqueResourceValue) => {
				return uniqueResourceValue.value === resourceValue;
			});
		if (!uniqueResource) {
			console.error(
				"commerce-screen-empire-tab: Unable to get unique resource value for selected empire resource",
			);
			return;
		}
		return GameInfo.Resources.lookup(uniqueResource.uniqueResource.resource);
	}

	const gamepadTrayItems: Accessor<GamepadTrayItem[]> = createMemo(() => {
		if (model.selectedEmpireResource()) {
			const selectedResourceDefinition = getResourceDefinitonFromResourceValue(model.selectedEmpireResource()!);
			if (selectedResourceDefinition) {
				const deselectResourceLabel = Locale.compose(
					"LOC_COMMERCE_GAMEPAD_STOP_VIEWING_CONTAINER_HINT",
					Locale.compose(selectedResourceDefinition.Name),
				);
				return [
					{
						hotkeyAction: "cancel",
						name: "cancel-empire-resource-edit",
						navTrayText: deselectResourceLabel,
						onActivate: () => model.setSelectedEmpireResource(),
					},
				] as GamepadTrayItem[];
			}
			console.warn(
				"commerce-screen-treasure-tab.tsx: When getting gamepadTrayItems, couldn't find city with ID",
				model.selectedTreasureConvoyId(),
			);
		} else if (focusedResourceCard()) {
			const focusedResourceDefinition = getResourceDefinitonFromResourceValue(focusedResourceCard()!);
			if (focusedResourceDefinition) {
				const selectResourceLabel = Locale.compose(
					"LOC_COMMERCE_GAMEPAD_VIEW_CONTAINER_HINT",
					Locale.compose(focusedResourceDefinition.Name),
				);
				return [
					{
						hotkeyAction: "accept",
						name: "empire-resource-edit",
						navTrayText: selectResourceLabel,
						// activate handled by activatable below
					},
				] as GamepadTrayItem[];
			}
		}
		return [];
	});

	return (
		<SpatialSlot
			name="Commerce-Screen-Empire-Tab"
			class="flex-auto"
		>
			<CommerceScreenBaseTabContent
				title="LOC_COMMERCE_EMPIRE_RESOURCE_TITLE"
				description="LOC_COMMERCE_EMPIRE_RESOURCES_DESCRIPTION"
			>
				<GamepadTrayItemProvider
					class="flex-auto"
					name="treasure-convoy-gamepad-items"
					items={gamepadTrayItems}
				>
					<ScrollArea
						class="flex-auto"
						useProxy
					>
						<div
							ref={cardsRowRef}
							class={`empire-resource-cards-row flex flex-row flex-wrap flex-auto relative ${isMobile() ? "pl-6" : ""}`}
							classList={{ "h-full justify-center": props.empireResourceData.length === 0 }}
						>
							<Show when={props.empireResourceData.length == 0}>
								<div class="text-secondary self-center text-center text-accent-2">
									<L10n.Compose text="LOC_COMMERCE_NO_EMPIRE_RESOURCES_DESCRIPTION" />
								</div>
							</Show>
							<For each={props.empireResourceData}>
								{(resourceData, index) => (
									<Activatable
										name={`${Locale.compose(resourceData.title)}-resource-card`}
										class="focusable-card-activatable"
										onFocus={() => setFocusedResourceCard(resourceData.resourceValue)}
										autoFocus={shouldAutoFocusResourceCard(resourceData.resourceValue, index())}
										onActivate={() => model.setSelectedEmpireResource(resourceData.resourceValue)}
										disabled={!IsControllerActive() || model.selectedEmpireResource() !== undefined}
										suppressPointerChanges
									>
										<OrnateCard
											iconSrc={resourceData.iconSrc}
											class={`flex flex-col items-center justify-between relative pb-1 empire-resource-card ${hasCheckedForWrap() ? "opacity-100" : "opacity-0"}`}
											style={{
												width:
													empireResourceCardWidth() !== undefined
														? empireResourceCardWidth()
														: defaultEmpireCardWidth() + "px",
												"margin-right":
													numCardsInFirstRow() === 0 ||
													(index() + 1) % numCardsInFirstRow() !== 0
														? empireCardMarginRight() + "px"
														: "0px",
											}}
											childrenInFront={
												<Icon
													class="absolute top-2 size-6"
													name={`url(blp:${resourceData.isTreasure ? "restype_treasure" : "restype_empire_v2"})`}
												/>
											}
										>
											<div class="flex flex-col w-full grow items-center mt-8">
												<div class="mb-2 w-full">
													<FiligreeTitle.Plain text={resourceData.title}>
														<div class="ml-1 text-white">{`[${resourceData.amount}]`}</div>
													</FiligreeTitle.Plain>
												</div>
												<div class="w-full text-center items-center flex-col px-2">
													<For each={resourceData.description}>
														{(description) => (
															<CardFrame class="w-full">
																<div class="flex flex-row items-center mb-1 px-2">
																	<Show when={resourceData.isCombatResource}>
																		<>
																			<Icon
																				class="size-8"
																				name="url(blp:pedia_combat)"
																			/>
																			<div class="mx-2 h-10 w-0\.5 bg-accent" />
																		</>
																	</Show>
																	<Show
																		when={
																			model.selectedEmpireResource() ===
																			resourceData.resourceValue
																		}
																		fallback={
																			<L10n.Stylize
																				class="py-1 self-center text-center"
																				text={description}
																				disableTooltips
																			/>
																		}
																	>
																		<L10n.Stylize
																			class="py-1 self-center text-center"
																			text={description}
																		/>
																	</Show>
																</div>
															</CardFrame>
														)}
													</For>
												</div>
											</div>
											<div class="flex flex-col w-full justify-center items-center mt-1 mb-1">
												<FiligreeTitle.Plain text="LOC_COMMERCE_EMPIRE_RESOURCES_ORIGIN_TITLE" />
												<div class="flex flex-row flex-wrap">
													<For each={resourceData.resourceOriginData}>
														{(originData, index) => (
															<Tooltip.Text
																header="LOC_COMMERCE_EMPIRE_ORIGIN_CITIES"
																text={resourceData.tooltips[originData.leaderId]}
																showFiligrees={false}
															>
																<Activatable
																	name="empire-resource-origin-portrait"
																	class="hover\:scale-125 focus\:scale-125"
																	autoFocus={
																		index() === 0 &&
																		model.selectedEmpireResource() ===
																			resourceData.resourceValue
																	}
																	disabled={
																		IsControllerActive() &&
																		model.selectedEmpireResource() !==
																			resourceData.resourceValue
																	}
																	suppressPointerChanges
																>
																	<PortraitIcon
																		class="-mx-2 -my-1"
																		{...{ playerId: originData.leaderId, size: 14 }}
																	/>
																</Activatable>
															</Tooltip.Text>
														)}
													</For>
												</div>
											</div>
										</OrnateCard>
									</Activatable>
								)}
							</For>
						</div>
					</ScrollArea>
				</GamepadTrayItemProvider>
			</CommerceScreenBaseTabContent>
		</SpatialSlot>
	);
};
//#endregion
